/*
 * CLIMATE CHANGE 11 — RISING SEAS / COASTAL FLOODGATE
 * 25 seconds | 3 scenes | seamless loop | UHD 3840 x 2160 | 60 fps
 * Interface: draw(ctx, timeInSeconds, width, height).
 * Pure, deterministic Canvas 2D. No DOM, libraries, fonts, or external assets.
 * Scene 1: tide sensing and an open, continuously moving water channel.
 * Scene 2: the sensor triggers the rack-and-pinion gate before the sea peaks.
 * Scene 3: a sealed gate, restrained seaward spray, and calmer protected water.
 * All structures are flat 2D sections. No people, animals, or 3D objects.
 * Static background. No glow, bloom, shadows, blur, or lighting effects.
 * VIDEO EXPORT: set the encoder to 100,000,000 bits/second (100 Mbps).
 * Canvas draws frames; the encoder must enforce the video export bitrate.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU=Math.PI*2,phase=TAU*loopT/duration;
  const ink='#344E62',cream='#E8E9DC',pale='#D5E6DE',blue='#739FAF',green='#8DB3A0',amber='#C8A283';
  function clamp(x){return Math.max(0,Math.min(1,x));}
  function mix(a,b,p){return a+(b-a)*p;}
  function mod(x){return((x%1)+1)%1;}
  function smooth(a,b,x){const q=clamp((x-a)/(b-a));return q*q*(3-2*q);}
  function stroke(c,w){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();}
  function line(x0,y0,x1,y1,c,w){ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1,y1);stroke(c,w);}
  function rr(x,y,w,h,r){
    r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
    ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
  }
  function box(x,y,w,h,r,fill,lw){rr(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();stroke(ink,lw||3.5);}
  function circle(x,y,r,fill,border,lw){ctx.beginPath();ctx.arc(x,y,r,0,TAU);if(fill){ctx.fillStyle=fill;ctx.fill();}if(border)stroke(border,lw||3);}
  function gradient(x0,y0,x1,y1,a,b){const g=ctx.createLinearGradient(x0,y0,x1,y1);g.addColorStop(0,a);g.addColorStop(1,b);return g;}
  function route(nodes,radius){
    const pts=[nodes[0]];
    for(let i=1;i<nodes.length-1;i++){
      const a=nodes[i-1],b=nodes[i],c=nodes[i+1],l0=Math.hypot(b[0]-a[0],b[1]-a[1]),l1=Math.hypot(c[0]-b[0],c[1]-b[1]);
      const d=Math.min(radius,l0*.4,l1*.4),u=[b[0]-(b[0]-a[0])*d/l0,b[1]-(b[1]-a[1])*d/l0],v=[b[0]+(c[0]-b[0])*d/l1,b[1]+(c[1]-b[1])*d/l1];pts.push(u);
      for(let j=1;j<=12;j++){const q=j/12,z=1-q;pts.push([z*z*u[0]+2*z*q*b[0]+q*q*v[0],z*z*u[1]+2*z*q*b[1]+q*q*v[1]]);}
    }
    pts.push(nodes[nodes.length-1]);const lengths=[0];for(let i=1;i<pts.length;i++)lengths.push(lengths[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));
    return{pts:pts,lengths:lengths,total:lengths[lengths.length-1]};
  }
  function at(r,q){
    const d=clamp(q)*r.total;for(let i=1;i<r.pts.length;i++)if(d<=r.lengths[i]){const u=(d-r.lengths[i-1])/(r.lengths[i]-r.lengths[i-1]);return[mix(r.pts[i-1][0],r.pts[i][0],u),mix(r.pts[i-1][1],r.pts[i][1],u)];}return r.pts[r.pts.length-1];
  }
  function trace(r,c,w){ctx.beginPath();ctx.moveTo(r.pts[0][0],r.pts[0][1]);for(let i=1;i<r.pts.length;i++)ctx.lineTo(r.pts[i][0],r.pts[i][1]);stroke(c,w);}
  function cable(r,active){trace(r,ink,10);trace(r,'#B9CCC6',4.8);for(let i=0;i<7;i++){
    const q=mod(loopT*3/duration+i/7),p=at(r,q);ctx.save();ctx.globalAlpha*=(.3+.7*active)*Math.pow(Math.sin(Math.PI*q),2);circle(p[0],p[1],1.8,cream);ctx.restore();
  }}
  const sensorWire=route([[-345,-185],[-345,-333],[335,-333],[335,-286]],18);
  const controlWire=route([[252,-220],[226,-220],[226,33],[202,33]],12);
  function wave(x,level,amplitude,protectedSide){
    return level+amplitude*Math.sin(x/69-phase*(protectedSide?3:6))+.36*amplitude*Math.sin(x/37+phase*(protectedSide?2:4));
  }
  function waterPath(x0,x1,level,amplitude,protectedSide){
    ctx.beginPath();ctx.moveTo(x0-2,260);ctx.lineTo(x0-2,wave(x0-2,level,amplitude,protectedSide));
    for(let x=x0-2;x<=x1+2;x+=4)ctx.lineTo(x,wave(x,level,amplitude,protectedSide));ctx.lineTo(x1+4,wave(x1+4,level,amplitude,protectedSide));ctx.lineTo(x1+4,260);ctx.closePath();
  }
  function waterBay(x0,x1,level,amplitude,protectedSide){
    ctx.save();rr(x0,-92,x1-x0,351,8);ctx.clip();
    waterPath(x0,x1,level,amplitude,protectedSide);ctx.fillStyle=gradient(0,-55,0,260,protectedSide?'#A1C3C1':'#82AFBD',protectedSide?'#6C9FAA':'#4C7E99');ctx.fill();
    // A second clipped wave gives depth through flat color, without 3D lighting.
    waterPath(x0,x1,level+49,amplitude*.46,protectedSide);ctx.fillStyle=protectedSide?'#81AFB4':'#6495AC';ctx.fill();
    ctx.beginPath();for(let x=x0-2;x<=x1+4;x+=4){const y=wave(x,level,amplitude,protectedSide);if(x===x0-2)ctx.moveTo(x,y);else ctx.lineTo(x,y);}stroke(pale,2.8);
    ctx.save();waterPath(x0,x1,level+17,amplitude,protectedSide);ctx.clip();
    for(let i=0;i<4;i++){
      const q=mod(loopT*(protectedSide?2:3)/duration+i/4);
      const a=protectedSide?176:-284,b=protectedSide?377:-51,x=mix(a,b,q),y=168+(i%2)*43;
      ctx.save();ctx.globalAlpha*=(protectedSide?.24:.38)*Math.pow(Math.sin(Math.PI*q),2);
      ctx.beginPath();ctx.moveTo(x-15,y);ctx.quadraticCurveTo(x,y+3,x+15,y);stroke(pale,2.1);ctx.restore();
    }
    ctx.restore();ctx.restore();
  }
  function channel(left,right,seal){
    ctx.save();ctx.beginPath();ctx.rect(38,-92,91,352);ctx.clip();
    const level=mix(left,right,.5);
    waterPath(38,129,level,1.8,false);ctx.fillStyle=blue;ctx.fill();
    if(seal<1){for(let i=0;i<3;i++){
      const q=mod(loopT*7/duration+i/3);ctx.save();ctx.globalAlpha*=(1-seal)*.42*Math.pow(Math.sin(Math.PI*q),2);
      line(mix(45,117,q),222+i*10,mix(45,117,q)+10,222+i*10,pale,2);ctx.restore();
    }}ctx.restore();
  }
  function sensor(level,amp,high){
    box(-350.5,-151,11,400,5,'#BFD5D0',2.7);
    for(let i=0;i<10;i++)line(-315,-94+i*35,-302+(i%2===0?6:0),-94+i*35,cream,2.3);
    box(-363,241,36,22,6,cream,3.0);
    box(-367,-185,44,36,9,cream,3.1);
    box(-355,-176,20,13,4,'#A6C5BC',1.9);
    for(let i=0;i<3;i++){
      ctx.save();ctx.globalAlpha*=.30+.70*Math.pow(.5+.5*Math.sin(phase*5-i*1.2),2);circle(-358+i*13,-158,2.0,high?amber:green);ctx.restore();
    }
    const y=wave(-345,level,amp,false);
    box(-366,y-12,42,24,9,cream,2.9);line(-345,y-8,-345,y+8,ink,3.1);
    line(-359,y,-352,y,blue,2.7);line(-338,y,-331,y,blue,2.7);
    circle(-345,-187,5,cream,ink,2.2);
  }
  function pinion(rotation){
    ctx.save();ctx.translate(162,33);ctx.rotate(rotation);
    const teeth=12,root=22.4,tip=25;
    ctx.beginPath();
    for(let i=0;i<teeth;i++)for(let j=0;j<4;j++){
      const a=(i+[.08,.24,.76,.92][j])*TAU/teeth,r=j===0||j===3?root:tip;
      const x=Math.cos(a)*r,y=Math.sin(a)*r;if(i===0&&j===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    }
    ctx.closePath();ctx.fillStyle=amber;ctx.fill();stroke(ink,2.7);
    for(let i=0;i<3;i++){const a=i*TAU/3;line(Math.cos(a)*8,Math.sin(a)*8,Math.cos(a)*16,Math.sin(a)*16,ink,2.1);}
    circle(0,0,7,cream,ink,2.5);circle(0,0,2.5,ink);ctx.restore();
  }
  function gate(seal){
    // The blade has a constant 89 x 340 silhouette. Only its parent translates.
    box(8,-306,156,40,12,gradient(8,-306,164,-266,'#E5E9DC','#B7CCBF'),4.1);
    box(20,-270,18,535,6,'#C1D1C7',3.2);box(128,-270,22,535,6,'#C1D1C7',3.2);
    box(148,-4,54,74,15,'#BDD2C6',3.1);box(194,21,15,24,4,cream,2.5);
    const displacement=192*seal,top=-270+displacement;
    ctx.save();ctx.translate(0,top);
    box(39,0,89,340,8,gradient(39,0,128,340,'#E4E8D9','#B3CFC2'),4.0);
    for(let i=0;i<6;i++)box(53,25+i*51,61,30,6,'#CBDDCE',2.0);
    box(39,329,89,11,3,'#829F99',2.6);
    for(const x of[47,120])for(const y of[12,318])circle(x,y,2.0,cream,ink,1.2);
    // The rack and pinion share a pitch of 2*pi*24 / 12.
    const pitch=TAU*24/12;
    ctx.beginPath();ctx.moveTo(128,2);ctx.lineTo(132,2);
    for(let y=6;y<329;y+=pitch){ctx.lineTo(132,y);ctx.lineTo(139,y+2);ctx.lineTo(139,y+6.4);ctx.lineTo(132,y+8.4);}
    ctx.lineTo(132,338);ctx.lineTo(128,338);ctx.closePath();ctx.fillStyle='#B6A78D';ctx.fill();stroke(ink,1.8);
    ctx.restore();
    // A descending rack turns its left-hand pinion contact counterclockwise.
    pinion(-displacement/24+.12);
    box(12,258,34,18,5,cream,2.9);box(122,258,36,18,5,cream,2.9);
    for(let i=0;i<4;i++)line(40+i*31,-286,53+i*31,-286,'#8AA99D',2.5);
  }
  function controller(level,seal,mode,p){
    box(252,-286,173,135,22,gradient(252,-286,425,-151,'#E5E7D8','#BBCDBE'),4.1);
    box(273,-265,131,62,10,'#C5D9CD',2.8);
    const value=clamp((106-level)/124);
    for(let i=0;i<7;i++){
      const h=10+i*5,on=smooth(i/8-.03,i/8+.05,value);
      rr(284+i*16,-213-h,9,h,2.8);ctx.fillStyle=i>4?amber:green;ctx.globalAlpha*=1;ctx.fill();
      ctx.save();ctx.globalAlpha*=.76*(1-on);rr(284+i*16,-213-h,9,h,2.8);ctx.fillStyle='#BDCFC4';ctx.fill();ctx.restore();
    }
    line(281,-234,395,-234,'#73968D',1.5);
    for(let i=0;i<3;i++){
      box(274+i*43,-189,35,22,6,cream,2.0);
      const on=i===0?value:i===1?seal:mode===2?1:seal*.6;
      ctx.save();ctx.globalAlpha*=.24+.76*on;rr(283+i*43,-181,17,6,3);ctx.fillStyle=mode===1&&i===0?amber:green;ctx.fill();ctx.restore();
    }
    if(mode===2){
      ctx.save();ctx.globalAlpha*=smooth(.03,.24,p);circle(410,-177,7,cream,ink,1.8);
      ctx.beginPath();ctx.moveTo(406.5,-177);ctx.lineTo(409,-174.5);ctx.lineTo(414,-179.5);stroke('#648F7C',1.9);ctx.restore();
    }
    box(325,-294,20,16,4,cream,2.4);box(243,-231,18,22,4,cream,2.3);
  }
  function spray(level,active){
    if(active<=0)return;
    for(let i=0;i<2;i++){
      const q=mod(loopT*8/duration+i*.5),x=9-(i===0?29:43)*q,y=level-55*q+56*q*q;
      ctx.save();ctx.globalAlpha*=active*.72*Math.pow(Math.sin(Math.PI*q),2);
      circle(x,y,mix(3.2,1.8,q),pale,ink,1.15);ctx.restore();
    }
  }
  function scene(mode,p,offset,alpha){
    if(alpha<=0)return;ctx.save();ctx.translate(offset,0);ctx.globalAlpha*=alpha;
    // A small measured rise precedes actuation; the larger surge arrives later.
    const preRise=mode===0?0:mode===1?smooth(.03,.15,p):1;
    const surge=mode===0?0:mode===1?smooth(.27,.82,p):1;
    const seal=mode===0?0:mode===1?smooth(.16,.46,p):1;
    const rise=(14*preRise+110*surge)/124;
    const left=106-124*rise,right=106-8*preRise;
    const amp=mix(3.4,6.3,rise),calm=mix(2.6,1.1,seal);
    cable(sensorWire,rise);cable(controlWire,seal);
    waterBay(-424,39,left,amp,false);channel(left,right,seal);waterBay(128,424,right,calm,true);
    box(-443,258,887,36,14,gradient(-443,258,444,294,'#E2E6D7','#B7CEC1'),4.3);
    box(-443,-93,19,361,7,'#D6E0D2',3.6);box(424,20,20,248,7,'#D6E0D2',3.6);
    for(let i=0;i<7;i++)line(-398+i*125,277,-367+i*125,277,'#8FAA9F',2.3);
    gate(seal);sensor(left,amp,rise>.4);controller(left,seal,mode,p);
    spray(left,mode===2?.76:mode===1?smooth(.66,.84,p):0);
    ctx.restore();
  }

  ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;ctx.shadowColor='rgba(0,0,0,0)';ctx.filter='none';ctx.setLineDash([]);
  const bg=ctx.createLinearGradient(0,0,width,height);bg.addColorStop(0,'#2B465F');bg.addColorStop(.54,'#5E8592');bg.addColorStop(1,'#A0B8B2');
  ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);ctx.translate(width/2,height/2+minSide*.023);ctx.scale(minSide/900,minSide/900);
  const transition=smooth(.84,1,sceneProgress),travel=1140;
  scene(currentScene,sceneProgress,-travel*transition,1-smooth(.72,1,transition));
  if(transition>0)scene((currentScene+1)%sceneCount,0,travel*(1-transition),smooth(0,.22,transition));
  ctx.restore();
}

/*
 * CLIMATE CHANGE 12 — METHANE CONTROL / WASTE GAS RECOVERY
 * 25 seconds | 3 scenes | seamless loop | UHD 3840 x 2160 | 60 fps
 * Interface: draw(ctx, timeInSeconds, width, height).
 * Pure, deterministic Canvas 2D. No DOM, libraries, fonts, or external assets.
 * Scene 1: a capped landfill section, collection wells, and an assembling header.
 * Scene 2: the valve opens, the blower accelerates, and recovered gas is stored.
 * Scene 3: collection continues, the storage piston rises, and source gas declines.
 * Qualitative schematic; meters do not represent measured emissions data.
 * Flat 2D sections only. No people, animals, plants, or 3D objects.
 * Static background. No glow, bloom, shadows, blur, or lighting effects.
 * VIDEO EXPORT: set the encoder to 100,000,000 bits/second (100 Mbps).
 * Canvas draws frames; the encoder must enforce the video export bitrate.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU=Math.PI*2,phase=TAU*loopT/duration;
  const ink='#4B5355',cream='#EDE7D7',pale='#D8E3CF',green='#8FAF9B',sand='#D1BA91',blue='#8FAFB3';
  function clamp(x){return Math.max(0,Math.min(1,x));}
  function mix(a,b,p){return a+(b-a)*p;}
  function mod(x){return((x%1)+1)%1;}
  function smooth(a,b,x){const q=clamp((x-a)/(b-a));return q*q*(3-2*q);}
  function stroke(c,w){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();}
  function line(x0,y0,x1,y1,c,w){ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1,y1);stroke(c,w);}
  function rr(x,y,w,h,r){
    r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
    ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
  }
  function box(x,y,w,h,r,fill,lw){rr(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();stroke(ink,lw||3.5);}
  function circle(x,y,r,fill,border,lw){ctx.beginPath();ctx.arc(x,y,r,0,TAU);if(fill){ctx.fillStyle=fill;ctx.fill();}if(border)stroke(border,lw||3);}
  function gradient(x0,y0,x1,y1,a,b){const g=ctx.createLinearGradient(x0,y0,x1,y1);g.addColorStop(0,a);g.addColorStop(1,b);return g;}
  function route(nodes,radius){
    const pts=[nodes[0]];
    for(let i=1;i<nodes.length-1;i++){
      const a=nodes[i-1],b=nodes[i],c=nodes[i+1],l0=Math.hypot(b[0]-a[0],b[1]-a[1]),l1=Math.hypot(c[0]-b[0],c[1]-b[1]);
      const d=Math.min(radius,l0*.4,l1*.4),u=[b[0]-(b[0]-a[0])*d/l0,b[1]-(b[1]-a[1])*d/l0],v=[b[0]+(c[0]-b[0])*d/l1,b[1]+(c[1]-b[1])*d/l1];pts.push(u);
      for(let j=1;j<=12;j++){const q=j/12,z=1-q;pts.push([z*z*u[0]+2*z*q*b[0]+q*q*v[0],z*z*u[1]+2*z*q*b[1]+q*q*v[1]]);}
    }
    pts.push(nodes[nodes.length-1]);const lengths=[0];for(let i=1;i<pts.length;i++)lengths.push(lengths[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));
    return{pts:pts,lengths:lengths,total:lengths[lengths.length-1]};
  }
  function at(r,q){
    const d=clamp(q)*r.total;for(let i=1;i<r.pts.length;i++)if(d<=r.lengths[i]){const u=(d-r.lengths[i-1])/(r.lengths[i]-r.lengths[i-1]);return[mix(r.pts[i-1][0],r.pts[i][0],u),mix(r.pts[i-1][1],r.pts[i][1],u)];}return r.pts[r.pts.length-1];
  }
  function trace(r,c,w,amount){
    amount=amount===undefined?1:clamp(amount);if(amount<=0)return;const d=r.total*amount;
    ctx.beginPath();ctx.moveTo(r.pts[0][0],r.pts[0][1]);
    for(let i=1;i<r.pts.length;i++){if(r.lengths[i]<=d)ctx.lineTo(r.pts[i][0],r.pts[i][1]);else{const p=at(r,amount);ctx.lineTo(p[0],p[1]);break;}}stroke(c,w);
  }
  function pipe(r,build,active){trace(r,ink,17,build);trace(r,cream,9,build);if(active>0){ctx.save();ctx.globalAlpha*=active;trace(r,green,5,build);ctx.restore();}}
  function packets(r,count,active,cycles){
    if(active<=0)return;for(let i=0;i<count;i++){
      const q=mod(loopT*cycles/duration+i/count),p=at(r,q),a0=at(r,clamp(q-.01)),a1=at(r,clamp(q+.01));
      ctx.save();ctx.globalAlpha*=active*Math.pow(Math.sin(Math.PI*q),2);ctx.translate(p[0],p[1]);ctx.rotate(Math.atan2(a1[1]-a0[1],a1[0]-a0[0]));
      rr(-4.2,-1.6,8.4,3.2,1.6);ctx.fillStyle=cream;ctx.fill();ctx.restore();
    }
  }
  function topPath(offset){
    ctx.moveTo(-440,20+offset);ctx.quadraticCurveTo(-411,-21+offset,-371,-28+offset);
    ctx.quadraticCurveTo(-324,-77+offset,-275,-81+offset);ctx.lineTo(-81,-81+offset);
    ctx.quadraticCurveTo(-22,-78+offset,24,-38+offset);ctx.quadraticCurveTo(84,-26+offset,117,20+offset);
  }
  function landfillPath(){
    ctx.beginPath();topPath(0);ctx.lineTo(117,259);ctx.quadraticCurveTo(117,278,98,278);ctx.lineTo(-421,278);
    ctx.quadraticCurveTo(-440,278,-440,259);ctx.closePath();
  }
  const pieces=[[-423,52,26,17,0],[-419,111,25,25,1],[-426,177,27,17,2],[-238,46,33,24,3],[-192,77,35,16,1],[-224,125,29,19,0],[-182,159,31,23,2],[-228,192,51,14,4],[18,61,30,19,1],[59,101,36,18,3],[9,149,34,24,2],[62,184,30,19,0],[21,224,68,15,4]];
