      const x = -194 + i * 80;
      rr(x, -246, 68, 19, 4); ctx.fillStyle = '#C59C80'; ctx.fill();
      const install = mode === 0 ? 0 : mode === 1 ? ease((p - 0.04 - i * 0.054) / 0.18) : 1;
      if (install > 0) {
