    const left = -408, right = 278;
    ctx.save(); ctx.globalAlpha *= active;
    ctx.beginPath(); ctx.moveTo(left, y + 7);
    ctx.bezierCurveTo(-349, y + 11, -276, y - 6, -189, y);
    stroke(cool, 2.4);
    ctx.beginPath(); ctx.moveTo(-154, y); ctx.lineTo(154, y); stroke('#87A9A5', 2.1);
    ctx.beginPath(); ctx.moveTo(189, y);
    ctx.bezierCurveTo(221, y, 246, y - 10, right, y - 7); stroke(cool, 2.4);

    for (let i = 0; i < 5; i++) {
      const q = mod(loopT * 4 / duration + i / 5 + row * 0.13);
      const x = mix(left, right, q);
      // Port housings are drawn afterward and naturally occlude passing packets.
      const dy = x < -189 ? 3.5 * Math.sin((x + 408) / 74)
        : x > 189 ? -7 * smooth(189, right, x) : 0;
      ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(Math.PI * q), 0.7);
      ctx.beginPath(); ctx.moveTo(x - 8, y + dy); ctx.lineTo(x + 8, y + dy); stroke(coolDark, 3.6);
      ctx.restore();
    }
    // A second short stream has its own lane and cannot intersect the first one.
    const q = mod(loopT * 5 / duration + row * 0.45);
    const x = mix(-389, -223, q);
    ctx.save(); ctx.globalAlpha *= 0.6 * Math.pow(Math.sin(Math.PI * q), 2);
    ctx.beginPath(); ctx.moveTo(x - 8, y - 12); ctx.lineTo(x + 8, y - 12); stroke(cool, 2.3);
