  function drawGroundFloor(active) {
    box(-37, 159, 74, 81, 6, '#899DA2', 3.3);
    ctx.beginPath(); ctx.moveTo(0, 164); ctx.lineTo(0, 239); stroke(ink, 2.3);
    circle(-9, 204, 2.2, cream); circle(9, 204, 2.2, cream);
    box(-139, 168, 65, 51, 8, cream, 3);
    circle(-106.5, 193.5, 17, '#D0D8CD', ink, 2.1);
    ctx.save(); ctx.translate(-106.5, 193.5); ctx.rotate(phase * 7);
    for (let i = 0; i < 4; i++) {
      ctx.save(); ctx.rotate(i * Math.PI / 2);
      ctx.beginPath(); ctx.moveTo(2, -2); ctx.quadraticCurveTo(6, -12, 11, -7);
      ctx.quadraticCurveTo(13, -1, 4, 1); ctx.closePath(); ctx.fillStyle = coolDark; ctx.fill(); ctx.restore();
    }
    ctx.restore(); circle(-106.5, 193.5, 3, ink);
    box(74, 168, 65, 51, 8, cream, 3);
    for (let i = 0; i < 3; i++) {
      const h = 10 + i * 8;
      rr(86 + i * 15, 207 - h, 8, h, 3);
      ctx.fillStyle = active > 0.4 ? cool : '#C49B83'; ctx.fill();
