  }
  function drawConfirmation(p) {
    const enter = smooth(0.24, 0.48, p);
    ctx.save(); ctx.globalAlpha *= enter;
    ctx.translate(0, 12 * (1 - enter));
    box(311, -53, 82, 38, 10, cream, 3.0);
    ctx.beginPath(); ctx.moveTo(331, -35); ctx.lineTo(341, -26); ctx.lineTo(365, -43);
