    const intro = mode === 0 ? smooth(0.01, 0.28, p) : 1;
    const active = mode === 0 ? 0 : mode === 1 ? smooth(0.40, 0.72, p) : 1;
    const heat = mode === 0 ? mix(0.77, 0.91, smooth(0.10, 0.75, p))
      : mode === 1 ? mix(0.91, 0.34, smooth(0.42, 0.83, p))
      : mix(0.34, 0.16, smooth(0.10, 0.74, p));
    drawBody(heat);
    const rows = [-155, -54, 47];
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        const i = row * 3 + col;
        const open = mode === 0 ? 0 : mode === 1 ? ease((p - 0.24 - i * 0.025) / 0.22) : 1;
        const show = mode === 0 ? smooth(0.01 + i * 0.015, 0.19 + i * 0.015, p) : 1;
        drawWindow(-136 + col * 100, rows[row], open, show, i);
