    }
    drawRoof(mode, p);
    drawHeatWaves(heat);
    drawGroundFloor(active);
    for (let row = 0; row < 2; row++) {
      const y = row === 0 ? -92 : 126;
      airflow(y, active, row);
      drawPort(-170, y, active); drawPort(170, y, active);
    }
    drawThermalDial(heat, active);
    if (mode === 2) drawConfirmation(p);
    box(-216, 241, 432, 22, 8, '#C9BFBB', 3.8);
    ctx.beginPath(); ctx.moveTo(-242, 265); ctx.lineTo(242, 265); stroke('#918A9A', 3.2);
    ctx.restore();
  }

  // 1.333-second slides keep full compositions in separate travel corridors.
  const transition = smooth(0.84, 1, sceneProgress);
  const travel = 1120;
  scene(currentScene, sceneProgress, -travel * transition, 1 - smooth(0.72, 1, transition));
  if (transition > 0)
    scene((currentScene + 1) % sceneCount, 0, travel * (1 - transition), smooth(0, 0.22, transition));
  ctx.restore();
}
